1974	func trailsBasePath(forge, owner, repo string) string {
1975		return fmt.Sprintf("/api/v1/trails/%s/%s/%s", forge, owner, repo)
1976	}
1977	
1978	// trailNumberPath returns the single-trail API path keyed by integer trail
1979	// number (e.g. "/api/v1/trails/gh/acme/repo/575"). The server validates an
1980	// integer here and rejects the trail UUID, so callers must pass Number, not ID.
1981	func trailNumberPath(forge, owner, repo string, number int) string {
1982		return trailsBasePath(forge, owner, repo) + "/" + strconv.Itoa(number)
1983	}
1984	
1985	// resolveTrailRemote resolves the origin remote and ensures the forge is
1986	// known to the trails API. Without this guard, an unmapped host (e.g.
1987	// gitlab.com, or a misconfigured entire:// URL with no forge prefix)
1988	// produces a malformed `/api/v1/trails//owner/repo` path that the server
1989	// rejects with an opaque error instead of a clear "unsupported forge" one.
1990	func resolveTrailRemote(ctx context.Context) (forge, owner, repo string, err error) {
1991		forge, owner, repo, err = gitremote.ResolveRemoteRepo(ctx, "origin")
1992		if err != nil {
1993			return "", "", "", fmt.Errorf("failed to resolve repository: %w", err)
1994		}
1995		if forge == "" {
1996			return "", "", "", errors.New("origin remote is not on a forge supported by Entire trails (supported: github.com)")
1997		}
1998		return forge, owner, repo, nil
1999	}
2000	
2001	// resolveTrailRepoOrRemote resolves the forge/owner/repo triple used to build
2002	// trail API paths. An explicit --repo override (repoOverride) wins; otherwise
2003	// it derives the triple from the origin remote of the current clone.
2004	func resolveTrailRepoOrRemote(ctx context.Context, repoOverride string) (forge, owner, repo string, err error) {
2005		if repoOverride != "" {
2006			return parseTrailRepoArg(repoOverride)
2007		}
2008		return resolveTrailRemote(ctx)
2009	}
2010	
2011	// resolveTrailBranch returns the branch a trail lookup should use: an explicit
2012	// --branch override (branchOverride) when given, otherwise the current branch.
2013	func resolveTrailBranch(ctx context.Context, branchOverride string) (string, error) {
2014		if branchOverride != "" {
2015			return branchOverride, nil
2016		}
2017		return GetCurrentBranch(ctx)
2018	}
2019	
2020	// parseTrailRepoArg parses an explicit --repo value into the forge/owner/repo
2021	// triple. It accepts the canonical "forge/owner/repo" form (e.g. gh/acme/app)
2022	// as well as a full clone URL (https://, git@, or entire://) that gitremote
2023	// can parse. A trailing ".git" on the repo is stripped.
2024	func parseTrailRepoArg(raw string) (forge, owner, repo string, err error) {
2025		raw = strings.TrimSpace(raw)
2026		if raw == "" {
2027			return "", "", "", errors.New("empty --repo value")
2028		}
2029		// Bare path form: forge/owner/repo. URLs (with a scheme or an SCP "@")
2030		// fall through to the URL parser, which understands hosts and schemes.
2031		if !strings.Contains(raw, "://") && !strings.Contains(raw, "@") {
2032			parts := strings.Split(strings.Trim(raw, "/"), "/")
2033			if len(parts) != 3 || parts[0] == "" || parts[1] == "" || parts[2] == "" {
2034				return "", "", "", fmt.Errorf("invalid --repo %q: expected forge/owner/repo (e.g. gh/acme/app) or a clone URL", raw)
2035			}
2036			// parts[0] must be a short forge id ("gh"), not a hostname. A host-like
