54	// registerMeTrails wires GET /me/trails: the caller's trails across every repo
55	// they are a member of. Like /cache/prs it is an enumeration (no {repo_id} to
56	// gate on), so it carries only requireAuth and does its own fail-closed access
57	// enumeration via the SpiceDB membership set (repo/list), NOT the pull set — a
58	// pull scope would flood it with every public repo's trails.
59	func registerMeTrails(api huma.API, deps *RepoActivityDeps) {
60		gate := []opMiddleware{requireAuth(api, &deps.baseDeps)}
61		huma.Register(api, teamOp("meTrails", http.MethodGet, "/me/trails",
62			"Your trails across your repositories", "me", gate),
63			func(ctx context.Context, in *MeTrailsInput) (*MeTrailsOutput, error) {
64				set, err := memberRepoSet(ctx, deps.Reader)
65				if err != nil {
66					return nil, err
67				}
68				ids, err := scopeAccountRepoIDs(ctx, deps, set, in.Repo)
69				if err != nil {
70					return nil, err
71				}
72				f := store.TrailsFilter{Statuses: splitCSV(in.Status), Limit: in.Limit}
73				if in.Author == "me" {
74					f.AuthorAccountID = id(ctx)
75				}
76				rows, total, err := deps.Store.TrailsForRepos(ctx, ids, f)
77				if err != nil {
78					return nil, huma.Error500InternalServerError("store: trails for repos", err)
79				}
80				out := &MeTrailsOutput{}
81				out.Body.Trails = meTrailItems(rows)
82				out.Body.Total = total
83				return out, nil
84			})
85	}
86	
87	// scopeAccountRepoIDs turns the member set into a []string of repo ids, and —
88	// when a repo filter is present — intersects it with the resolved filter ids so
89	// the filter can only narrow, never widen, access.
90	func scopeAccountRepoIDs(ctx context.Context, deps *RepoActivityDeps, set map[string]struct{}, repoFilter []string) ([]string, error) {
91		if len(repoFilter) == 0 {
92			ids := make([]string, 0, len(set))
93			for repoID := range set {
94				ids = append(ids, repoID)
95			}
96			return ids, nil
97		}
98		var ids []string
99		for _, spec := range repoFilter {
100			fullName, ok := fullNameFromRepoSpec(spec)
101			if !ok {
102				continue
103			}
104			repoID, found, err := deps.Store.RepoIDByFullName(ctx, fullName)
105			if err != nil {
106				return nil, huma.Error500InternalServerError("store: repo id by full name", err)
107			}
108			if !found {
109				continue
110			}
111			if _, member := set[repoID]; member {
112				ids = append(ids, repoID)
113			}
114		}
115		return ids, nil
116	}
117	
118	// fullNameFromRepoSpec parses "forge/owner/repo" (e.g. gh/acme/app) into the
119	// "owner/repo" full_name RepoIDByFullName expects. A bare "owner/repo" is also
120	// accepted. Anything else is skipped by the caller.
121	func fullNameFromRepoSpec(spec string) (string, bool) {
122		parts := strings.Split(strings.Trim(strings.TrimSpace(spec), "/"), "/")
123		if len(parts) == 3 { // drop the leading forge segment (e.g. gh/)
124			parts = parts[1:]
125		}
126		if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
127			return "", false
128		}
129		return parts[0] + "/" + parts[1], true
130	}
131	
132	func splitCSV(s string) []string {
133		s = strings.TrimSpace(s)
134		if s == "" {
135			return nil
136		}
137		var out []string
138		for _, p := range strings.Split(s, ",") {
139			if p = strings.TrimSpace(p); p != "" {
140				out = append(out, p)
141			}
142		}
143		return out
144	}
145	
146	func meTrailItems(rows []store.AccountTrailRow) []meTrailItem {
147		out := make([]meTrailItem, 0, len(rows))
148		for _, r := range rows {
149			var author *meTrailAuthor
150			if r.AuthorAccountID != "" {
151				author = &meTrailAuthor{ID: r.AuthorAccountID}
152			}
153			out = append(out, meTrailItem{
154				ID:              r.ID,
155				Number:          r.Number,
156				Title:           r.Title,
157				Status:          r.Status,
158				Branch:          r.Branch,
159				Base:            r.Base,
160				Author:          author,
161				CommentCount:    r.CommentCount,
162				UnresolvedCount: r.UnresolvedCount,
163				CreatedAt:       isoTime(r.CreatedAt),
164				UpdatedAt:       isoTime(r.UpdatedAt),
165				RepoFullName:    r.RepoFullName,
166				IsPrivate:       r.IsPrivate,
167			})
168		}
169		return out
170	}

