// TrailsListByRepoIDInput is the {repo_id}-addressed twin of TrailsListInput.
type TrailsListByRepoIDInput struct {
	RepoID    string `path:"repo_id" doc:"Repo id (ULID)"`
	PageSize  int    `query:"pageSize" minimum:"1" maximum:"100" default:"50" doc:"Page size, clamped to 1..100"`
