// --- list pagination cursor (opaque base64 over (updatedAt, id)) -------

// trailsCursor is the wire shape of the list route's pageToken: an opaque
// base64 blob wrapping the keyset position, same shape as
// encodeSessionsCursor/decodeSessionsCursor (checkpointapi.go) but with its
// own type — the two surfaces' cursors are not interchangeable.
type trailsCursor struct {
	UpdatedAt string `json:"updatedAt"`
	ID        string `json:"id"`
}

// encodeTrailsPageToken builds the opaque pageToken for the row a page ends
// on, so the next request's pageToken picks up immediately after it.
func encodeTrailsPageToken(updatedAt time.Time, id string) string {
	b, _ := json.Marshal(trailsCursor{UpdatedAt: updatedAt.Format(time.RFC3339Nano), ID: id})
	return base64.RawURLEncoding.EncodeToString(b)
}

// decodeTrailsPageToken decodes a pageToken into a store.TrailCursor. An
// empty token is the first page (nil cursor, nil error); anything present
// but unparseable is a caller error the handler turns into a 400 — unlike
// decodeSessionsCursor, a bad trails pageToken is never silently treated as
// the first page.
func decodeTrailsPageToken(token string) (*store.TrailCursor, error) {
	if token == "" {
		return nil, nil
	}
	raw, err := base64.RawURLEncoding.DecodeString(token)
	if err != nil {
		return nil, err
	}
	var c trailsCursor
	if err := json.Unmarshal(raw, &c); err != nil {
		return nil, err
	}
	if c.ID == "" {
		return nil, errors.New("pageToken: missing id")
	}
	if _, err := ulid.Parse(c.ID); err != nil {
		return nil, fmt.Errorf("pageToken: invalid id: %w", err)
	}
	t, err := time.Parse(time.RFC3339Nano, c.UpdatedAt)
	if err != nil {
		return nil, err
	}
	return &store.TrailCursor{UpdatedAt: t, ID: c.ID}, nil
