package httpapi

import (
	"context"
	"net/http"
	"strings"

	"github.com/danielgtaylor/huma/v2"

	"github.com/entirehq/entire-api/internal/store"
)

// meTrailItem is one account-scoped trail: the standard TrailListItem wire shape
// plus the owning repo (account rows span many repos). Field casing matches the
// repo-scoped trails list (camelCase), so /me/trails and /trails/... share one
// item contract.
type meTrailItem struct {
	TrailListItem
	RepoFullName string `json:"repoFullName"`
	IsPrivate    bool   `json:"isPrivate"`
}

// MeTrailsInput is the query for GET /me/trails. Pagination mirrors the
// repo-scoped list (pageSize + opaque pageToken); status/author/repo are the
// account-list filters.
type MeTrailsInput struct {
	Status    string   `query:"status" doc:"Comma-separated statuses; omit for all"`
	Author    string   `query:"author" doc:"'me' filters to the caller's own trails"`
	Repo      []string `query:"repo,explode" doc:"forge/owner/repo to narrow to; repeatable"`
	PageSize  int      `query:"pageSize" minimum:"1" maximum:"100" default:"50" doc:"Page size, clamped to 1..100"`
	PageToken string   `query:"pageToken" doc:"Opaque cursor from a prior nextPageToken"`
}

// MeTrailsOutput is the account-scoped list envelope: the same
// {items,nextPageToken} shape as the repo-scoped trails list.
type MeTrailsOutput struct {
	Body struct {
		Items         []meTrailItem `json:"items"`
		NextPageToken *string       `json:"nextPageToken"`
	}
}

// registerMeTrails wires GET /me/trails: the caller's trails across every repo
// they are a member of. Like /cache/prs it is an enumeration (no {repo_id} to
// gate on), so it carries only requireAuth and does its own fail-closed access
// enumeration via the SpiceDB membership set (repo/list), NOT the pull set — a
// pull scope would flood it with every public repo's trails.
func registerMeTrails(api huma.API, deps *RepoActivityDeps) {
	gate := []opMiddleware{requireAuth(api, &deps.baseDeps)}
	huma.Register(api, teamOp("meTrails", http.MethodGet, "/me/trails",
		"Your trails across your repositories", "me", gate),
		func(ctx context.Context, in *MeTrailsInput) (*MeTrailsOutput, error) {
			after, err := decodeTrailsPageToken(in.PageToken)
			if err != nil {
				return nil, huma.Error400BadRequest("invalid pageToken", err)
			}
			set, err := memberRepoSet(ctx, deps.Reader)
			if err != nil {
				return nil, err
			}
			ids, err := scopeAccountRepoIDs(ctx, deps, set, in.Repo)
			if err != nil {
				return nil, err
			}
			f := store.TrailsFilter{Statuses: splitCSV(in.Status)}
			if in.Author == "me" {
				f.AuthorAccountID = id(ctx)
			}
			pageSize := clampLimit(in.PageSize, trailsListDefaultPageSize, trailsListMaxPageSize)
			rows, err := deps.Store.TrailsForRepos(ctx, ids, f, pageSize, after)
			if err != nil {
				return nil, huma.Error500InternalServerError("store: trails for repos", err)
			}
			// pageSize+1 rows means there's a next page — trim and cursor from
			// the last returned row (same convention as trailsListCore).
			var nextPageToken *string
			if len(rows) > pageSize {
				rows = rows[:pageSize]
				last := rows[len(rows)-1]
				token := encodeTrailsPageToken(last.UpdatedAt, last.ID)
				nextPageToken = &token
			}
			logins := resolveAuthorLogins(ctx, deps, accountTrailListRows(rows))
			items := make([]meTrailItem, 0, len(rows))
			for _, r := range rows {
				items = append(items, meTrailItem{
					TrailListItem: toTrailListItem(r.TrailListRow, logins),
					RepoFullName:  r.RepoFullName,
					IsPrivate:     r.IsPrivate,
				})
			}
			out := &MeTrailsOutput{}
			out.Body.Items = items
			out.Body.NextPageToken = nextPageToken
			return out, nil
		})
}

// accountTrailListRows extracts the embedded TrailListRow slice so the shared
// resolveAuthorLogins (which takes []store.TrailListRow) can batch-resolve the
// author logins for account rows.
func accountTrailListRows(rows []store.AccountTrailRow) []store.TrailListRow {
	out := make([]store.TrailListRow, len(rows))
	for i, r := range rows {
		out[i] = r.TrailListRow
	}
	return out
}

// scopeAccountRepoIDs turns the member set into a []string of repo ids, and —
// when a repo filter is present — intersects it with the resolved filter ids so
// the filter can only narrow, never widen, access.
func scopeAccountRepoIDs(ctx context.Context, deps *RepoActivityDeps, set map[string]struct{}, repoFilter []string) ([]string, error) {
	if len(repoFilter) == 0 {
		ids := make([]string, 0, len(set))
		for repoID := range set {
			ids = append(ids, repoID)
		}
		return ids, nil
	}
	var ids []string
	for _, spec := range repoFilter {
		fullName, ok := fullNameFromRepoSpec(spec)
		if !ok {
			continue
		}
		repoID, found, err := deps.Store.RepoIDByFullName(ctx, fullName)
		if err != nil {
			return nil, huma.Error500InternalServerError("store: repo id by full name", err)
		}
		if !found {
			continue
		}
		if _, member := set[repoID]; member {
			ids = append(ids, repoID)
		}
	}
	return ids, nil
}

// fullNameFromRepoSpec parses "forge/owner/repo" (e.g. gh/acme/app) into the
// "owner/repo" full_name RepoIDByFullName expects. A bare "owner/repo" is also
// accepted. Anything else is skipped by the caller.
func fullNameFromRepoSpec(spec string) (string, bool) {
	parts := strings.Split(strings.Trim(strings.TrimSpace(spec), "/"), "/")
	if len(parts) == 3 { // drop the leading forge segment (e.g. gh/)
		parts = parts[1:]
	}
	if len(parts) != 2 || parts[0] == "" || parts[1] == "" {
		return "", false
	}
	return parts[0] + "/" + parts[1], true
}

func splitCSV(s string) []string {
	s = strings.TrimSpace(s)
	if s == "" {
		return nil
	}
	var out []string
	for _, p := range strings.Split(s, ",") {
		if p = strings.TrimSpace(p); p != "" {
			out = append(out, p)
		}
	}
	return out
}

