// MeTrailItem is one item of GET /api/v1/me/trails (entire-api account-scoped
// list). Its casing is entire-api's native camelCase — distinct from the
// snake_case repo-scoped BFF TrailResource — plus repoFullName/isPrivate.
type MeTrailItem struct {
	ID             string        `json:"id"`
	Number         int           `json:"number"`
	Title          string        `json:"title"`
	Status         string        `json:"status"`
	Branch         *string       `json:"branch"`
	OriginalBranch *string       `json:"originalBranch"`
	Base           string        `json:"base"`
	Type           string        `json:"type"`
	Priority       string        `json:"priority"`
	Author         *trail.Author `json:"author"`
	Phase          *string       `json:"phase"`
	CreatedAt      string        `json:"createdAt"`
	UpdatedAt      string        `json:"updatedAt"`
	MergedAt       *string       `json:"mergedAt"`
	RepoFullName   string        `json:"repoFullName"`
	IsPrivate      bool          `json:"isPrivate"`
}

// MeTrailsResponse is the GET /api/v1/me/trails envelope: keyset pagination
// (items + opaque nextPageToken), matching entire-api's repo-scoped trails list.
type MeTrailsResponse struct {
	Items         []MeTrailItem `json:"items"`
	NextPageToken *string       `json:"nextPageToken"`
}

// ToMetadata converts a MeTrailItem to a trail.Metadata for display. Branch
// falls back to originalBranch (matches the server's history-branch
// derivation); ISO timestamps parse best-effort (zero time on failure); the
// browser URL is built from repoFullName + number (forge is gh — the only forge
// Entire trails support).
func (i *MeTrailItem) ToMetadata() *trail.Metadata {
	branch := ""
	switch {
	case i.Branch != nil:
		branch = *i.Branch
	case i.OriginalBranch != nil:
		branch = *i.OriginalBranch
	}
	phase := ""
	if i.Phase != nil {
		phase = *i.Phase
	}
	m := &trail.Metadata{
		Number:       i.Number,
		TrailID:      trail.ID(i.ID),
		Branch:       branch,
		Base:         i.Base,
		Title:        i.Title,
		Status:       trail.Status(i.Status),
		Phase:        phase,
		Author:       i.Author,
		Type:         trail.Type(i.Type),
		Priority:     trail.Priority(i.Priority),
		RepoFullName: i.RepoFullName,
		IsPrivate:    i.IsPrivate,
		Assignees:    []string{},
		Labels:       []string{},
	}
	if t, err := time.Parse(time.RFC3339, i.CreatedAt); err == nil {
		m.CreatedAt = t
	}
	if t, err := time.Parse(time.RFC3339, i.UpdatedAt); err == nil {
		m.UpdatedAt = t
	}
	if i.MergedAt != nil {
		if t, err := time.Parse(time.RFC3339, *i.MergedAt); err == nil {
			m.MergedAt = &t
		}
	}
	if i.Number > 0 && i.RepoFullName != "" {
		m.URL = strings.TrimRight(BaseURL(), "/") + "/gh/" + i.RepoFullName + "/trails/" + strconv.Itoa(i.Number)
	}
	return m
}

